//! The harness of lean-runtime's micro-benchmarks (`benches/README.md`). Each binary in `src/bin/`
//! (generated by `scripts/gen_benches.py`) times one function of `lean_runtime::semantics` as a
//! translator's code would call it; its native twin of the same name in `benches/native/` makes
//! the same calls through Lean's API, on the same operands, and prints the same checksum.
//!
//! What both sides share, value for value with `benches/native/Bench/Harness.lean`:
//! - the LCG `step` and its seeds;
//! - the inputs, built before the first clock read: operand arrays (`f64_operands`), position
//!   arrays (`pos_input`), the strings (`mixed`, `ascii`, `variants`);
//! - the checksum: `mix` of every result; a float result enters through `fbits`/`gbits`, which are
//!   out of line as Lean's `Float.toBits`/`Float32.toBits` are;
//! - the glue a translator pays where Lean's API boxes: `nat_box`/`nat_unbox` (a `Nat` word as
//!   Lean's and lean2rr's: `2n+1` below 2^63), `int_box`/`int_unbox` (an `Int` word: `2i+1` in the
//!   `int32` range), `make_string`/`make_ascii_string` (a new string object: one allocation of a
//!   32-byte header, the bytes and a NUL, the characters counted unless known ASCII).
//!
//! A binary takes one argument, the number of iterations N. It prints the checksum on stdout line 1
//! and `kernel_ns <ns>` on line 2: monotonic time read just before the kernel and just after it,
//! the input built before and the result consumed after, both through `black_box`. The allocator is
//! mimalloc, as in Lean's runtime and both translators.

#![forbid(unsafe_code)]

use std::fmt;
use std::hint::black_box;
use std::time::Instant;

use lean_runtime::semantics::bignum::{BigInt, BigNat};
use lean_runtime::semantics::int::Int;
use lean_runtime::semantics::nat::Nat;
use lean_runtime::semantics::panic::InternalPanic;
use lean_runtime::semantics::{float, float32, string};

#[global_allocator]
static GLOBAL: mimalloc::MiMalloc = mimalloc::MiMalloc;

/// The LCG both sides draw their operands from: `x' = x * A + C` modulo 2^64.
#[inline(always)]
pub fn step(x: u64) -> u64 {
    x.wrapping_mul(6364136223846793005)
        .wrapping_add(1442695040888963407)
}

/// The LCG's first state in the timed loop.
pub const SEED: u64 = 0x9E37_79B9_7F4A_7C15;

/// The LCG's first state when the inputs are built.
pub const INPUT_SEED: u64 = 0x2545_F491_4F6C_DD1D;

/// The number of entries of an operand or position array (a power of two: the loop indexes it
/// with the top 12 bits of the LCG state).
pub const ARRAY: usize = 4096;

/// The checksum step: rotate and xor, so every bit of every result counts.
#[inline(always)]
pub fn mix(acc: u64, r: u64) -> u64 {
    acc.rotate_left(7) ^ r
}

/// A `Float` result's bits for the checksum, out of line as Lean's `Float.toBits`
/// (`lean_float_to_bits`, an extern call) is, so both sides pay the same consumption.
#[inline(never)]
pub fn fbits(x: f64) -> u64 {
    float::to_bits(x)
}

/// A `Float32` result's bits for the checksum (`lean_float32_to_bits`, out of line).
#[inline(never)]
pub fn gbits(x: f32) -> u64 {
    u64::from(float32::to_bits(x))
}

// ---------------------------------------------------------------- the glue a translator pays

/// A `Nat` word as Lean's C (`lean_usize_to_nat`) and lean2rr make it: `2n + 1` for `n < 2^63`.
/// The benchmarks never pass a bigger one; it would be a big number (an allocation) in Lean.
#[inline(always)]
pub fn nat_box(n: u64) -> u64 {
    if n >> 63 == 0 {
        (n << 1) | 1
    } else {
        big()
    }
}

/// The value of a `Nat` word (`lean_unbox` after `lean_is_scalar`); a big one reads as past
/// every string's end.
#[inline(always)]
pub fn nat_unbox(w: u64) -> u64 {
    if w & 1 == 1 {
        w >> 1
    } else {
        big()
    }
}

/// An `Int` word as Lean's C makes it on 64-bit platforms: `2i + 1` for `i` in the `int32` range.
#[inline(always)]
pub fn int_box(i: i64) -> u64 {
    if i32::try_from(i).is_ok() {
        (u64::from(i as u32) << 1) | 1
    } else {
        big()
    }
}

/// The value of an `Int` word.
#[inline(always)]
pub fn int_unbox(w: u64) -> i64 {
    if w & 1 == 1 {
        i64::from((w >> 1) as u32 as i32)
    } else {
        big() as i64
    }
}

/// The big-number path, which no benchmark takes.
#[cold]
#[inline(never)]
pub fn big() -> u64 {
    u64::MAX
}

/// The size of Lean's string header (`lean_string_object`: the object header, size, capacity,
/// length), which a translator's string block also carries (lean2rr's `LStr`).
const HEADER: usize = 32;

/// A new string object, as Lean's `lean_mk_string_unchecked` makes one: one allocation of the
/// header, the bytes and a NUL.
pub struct NewString(Vec<u8>);

impl NewString {
    /// `String.utf8ByteSize`.
    #[inline]
    pub fn byte_size(&self) -> u64 {
        (self.0.len() - HEADER - 1) as u64
    }
}

#[inline(always)]
fn new_string(b: &[u8], chars: u64) -> NewString {
    let mut v = Vec::with_capacity(HEADER + b.len() + 1);
    v.extend_from_slice(&[0u8; 8]); // the object header (count, tag)
    v.extend_from_slice(&(b.len() as u64 + 1).to_le_bytes()); // size
    v.extend_from_slice(&(b.len() as u64 + 1).to_le_bytes()); // capacity
    v.extend_from_slice(&chars.to_le_bytes()); // length
    v.extend_from_slice(b);
    v.push(0);
    NewString(v)
}

/// A new string of valid UTF-8 bytes, its characters counted
/// (`lean_mk_string_from_bytes_unchecked`).
#[inline]
pub fn make_string(b: &[u8]) -> NewString {
    new_string(b, string::utf8_strlen(b))
}

/// A new string of ASCII bytes, the count known (`lean_mk_ascii_string_unchecked`).
#[inline]
pub fn make_ascii_string(b: &[u8]) -> NewString {
    new_string(b, b.len() as u64)
}

/// A stack buffer for formatting (`Float.toString` writes at most 317 bytes).
pub struct StackBuf {
    buf: [u8; 384],
    len: usize,
}

impl StackBuf {
    #[inline(always)]
    pub fn new() -> StackBuf {
        StackBuf {
            buf: [0; 384],
            len: 0,
        }
    }

    #[inline(always)]
    pub fn as_bytes(&self) -> &[u8] {
        &self.buf[..self.len]
    }
}

impl Default for StackBuf {
    fn default() -> StackBuf {
        StackBuf::new()
    }
}

impl fmt::Write for StackBuf {
    #[inline(always)]
    fn write_str(&mut self, s: &str) -> fmt::Result {
        let end = self.len + s.len();
        match self.buf.get_mut(self.len..end) {
            Some(dst) => {
                dst.copy_from_slice(s.as_bytes());
                self.len = end;
                Ok(())
            }
            None => Err(fmt::Error),
        }
    }
}

// ---------------------------------------------------------------- inputs

/// The strings of the string benchmarks: 64 copies of "a€😀é0123" (characters of 1 to 4 bytes,
/// 896 bytes), as `Bench.mixed`.
pub fn mixed() -> String {
    "a€😀é0123".repeat(64)
}

/// 896 bytes of ASCII, as `Bench.ascii`.
pub fn ascii() -> String {
    "abcdefgh012345".repeat(64)
}

/// 16 strings that differ from `mixed()` at different depths (variant k has a `b` for the `a`
/// that starts chunk 4k, for k < 15; the last is `mixed()` itself), as `Bench.variants`.
pub fn variants() -> Vec<String> {
    let base = mixed();
    let mut out: Vec<String> = (0..15)
        .map(|k| {
            let at = 14 * 4 * k;
            format!("{}b{}", &base[..at], &base[at + 1..])
        })
        .collect();
    out.push(base);
    out
}

/// The special values mixed into an operand array: NaN, -NaN, inf, -inf, 0, -0, the largest
/// finite value and the smallest subnormal.
const SPECIALS: [u64; 8] = [
    0x7FF8_0000_0000_0000,
    0xFFF8_0000_0000_0000,
    0x7FF0_0000_0000_0000,
    0xFFF0_0000_0000_0000,
    0,
    0x8000_0000_0000_0000,
    0x7FEF_FFFF_FFFF_FFFF,
    1,
];

/// `ARRAY` operands uniform in `[lo, lo + width)` (`lo` and `width` given by their bits), every
/// eighth one a special value when `specials`, as `Bench.f64Operands`.
pub fn f64_operands(lo: u64, width: u64, specials: bool) -> Vec<f64> {
    let (lo, width) = (f64::from_bits(lo), f64::from_bits(width));
    let scale = f64::from_bits(0x3CA0_0000_0000_0000); // 2^-53
    let mut x = INPUT_SEED;
    (0..ARRAY)
        .map(|k| {
            x = step(x);
            if specials && k % 8 == 7 {
                f64::from_bits(SPECIALS[(k / 8) % 8])
            } else {
                lo + ((x >> 11) as f64 * scale) * width
            }
        })
        .collect()
}

/// Two operand arrays, for the binary functions, as `Bench.f64Pairs`.
pub fn f64_pairs(lo: u64, width: u64, lo2: u64, width2: u64) -> (Vec<f64>, Vec<f64>) {
    let ys: Vec<f64> = f64_operands(lo2, width2, false).into_iter().rev().collect();
    (f64_operands(lo, width, false), ys)
}

/// The operand at index `j` (`FloatArray.get!`: 0 out of range).
#[inline(always)]
pub fn get_f64(xs: &[f64], j: u64) -> f64 {
    match xs.get(j as usize) {
        Some(&v) => v,
        None => 0.0,
    }
}

/// A string and `ARRAY` positions in it as `Nat` words, as `Bench.PosInput`.
pub struct PosInput {
    pub s: String,
    pub ps: Vec<u64>,
}

/// Which positions a `PosInput` holds.
#[derive(Clone, Copy)]
pub enum Positions {
    /// Any byte position up to two past the end.
    Any,
    /// A byte position before the end.
    Inside,
    /// A character start before the end.
    Starts,
    /// A character start or the end.
    Valid,
}

/// The positions of `s` of a kind, drawn with the LCG, as `Bench.posInput`.
pub fn pos_input(s: String, kind: Positions) -> PosInput {
    let len = s.len() as u64;
    let starts: Vec<u64> = s
        .char_indices()
        .map(|(i, _)| i as u64)
        .chain(std::iter::once(len))
        .collect();
    let mut x = INPUT_SEED;
    let ps = (0..ARRAY)
        .map(|_| {
            x = step(x);
            let p = match kind {
                Positions::Any => x % (len + 2),
                Positions::Inside => x % len,
                Positions::Starts => starts[(x % (starts.len() as u64 - 1)) as usize],
                Positions::Valid => starts[(x % starts.len() as u64) as usize],
            };
            nat_box(p)
        })
        .collect();
    PosInput { s, ps }
}

/// The `Nat` word at index `j` (`Array.get!`: 0 out of range).
#[inline(always)]
pub fn get_word(ps: &[u64], j: u64) -> u64 {
    match ps.get(j as usize) {
        Some(&w) => w,
        None => 1,
    }
}

/// The string at index `j` (`Array.get!`: the default, "", out of range).
#[inline(always)]
pub fn get_str(ss: &[String], j: u64) -> &[u8] {
    match ss.get(j as usize) {
        Some(s) => s.as_bytes(),
        None => b"",
    }
}

// ---------------------------------------------------------------- Nat, Int, arrays, text (batch 2)

/// The big-number backend of the `Nat`/`Int` benchmarks. Their operands and results stay words, so
/// no method runs; each is an out-of-line cold call, as a translator's big-number path is, so that
/// a rule's word path compiles as it would in a translator's glue.
pub struct ColdBig(pub u64);

#[cold]
#[inline(never)]
fn cold_big() -> ColdBig {
    ColdBig(black_box(0))
}

#[cold]
#[inline(never)]
fn cold_u64() -> u64 {
    black_box(0)
}

#[cold]
#[inline(never)]
fn cold_order() -> core::cmp::Ordering {
    black_box(core::cmp::Ordering::Equal)
}

#[cold]
#[inline(never)]
fn cold_fmt() -> fmt::Result {
    black_box(Ok(()))
}

impl BigNat for ColdBig {
    fn from_u64(_: u64) -> ColdBig {
        cold_big()
    }
    fn to_u64(&self) -> Option<u64> {
        Some(cold_u64())
    }
    fn low_u64(&self) -> u64 {
        cold_u64()
    }
    fn bit_len(&self) -> u64 {
        cold_u64()
    }
    fn compare(&self, _: &ColdBig) -> core::cmp::Ordering {
        cold_order()
    }
    fn add(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn add_u64(self, _: u64) -> ColdBig {
        cold_big()
    }
    fn sub(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn sub_u64(self, _: u64) -> ColdBig {
        cold_big()
    }
    fn mul(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn mul_u64(self, _: u64) -> ColdBig {
        cold_big()
    }
    fn div(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn rem(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn div_u64(self, _: u64) -> ColdBig {
        cold_big()
    }
    fn rem_u64(&self, _: u64) -> u64 {
        cold_u64()
    }
    fn and(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn or(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn or_u64(self, _: u64) -> ColdBig {
        cold_big()
    }
    fn xor(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn xor_u64(self, _: u64) -> ColdBig {
        cold_big()
    }
    fn shl(self, _: u64) -> ColdBig {
        cold_big()
    }
    fn shr(self, _: u64) -> ColdBig {
        cold_big()
    }
    fn pow(self, _: u32) -> ColdBig {
        cold_big()
    }
    fn gcd(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn write_decimal<W: fmt::Write + ?Sized>(&self, _: &mut W) -> fmt::Result {
        cold_fmt()
    }
}

impl BigInt for ColdBig {
    type Nat = ColdBig;
    fn from_i64(_: i64) -> ColdBig {
        cold_big()
    }
    fn from_i128(_: i128) -> ColdBig {
        cold_big()
    }
    fn from_nat(_: ColdBig) -> ColdBig {
        cold_big()
    }
    fn nat_abs(self) -> ColdBig {
        cold_big()
    }
    fn to_i64(&self) -> Option<i64> {
        Some(cold_u64() as i64)
    }
    fn low_u64(&self) -> u64 {
        cold_u64()
    }
    fn is_neg(&self) -> bool {
        cold_u64() != 0
    }
    fn compare(&self, _: &ColdBig) -> core::cmp::Ordering {
        cold_order()
    }
    fn neg(self) -> ColdBig {
        cold_big()
    }
    fn add(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn sub(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn mul(self, _: ColdBig) -> ColdBig {
        cold_big()
    }
    fn tdiv_rem(self, _: &ColdBig) -> (ColdBig, ColdBig) {
        (cold_big(), cold_big())
    }
    fn write_decimal<W: fmt::Write + ?Sized>(&self, _: &mut W) -> fmt::Result {
        cold_fmt()
    }
}

/// A `Nat` word as the rules take it: a word's value, or a big number (never in the benchmarks).
#[inline(always)]
pub fn nat_arg(w: u64) -> Nat<ColdBig> {
    if w & 1 == 1 {
        Nat::Small(w >> 1)
    } else {
        Nat::Big(cold_big())
    }
}

/// A rule's `Nat` result as a word (a big result, never in the benchmarks, is the big path).
#[inline(always)]
pub fn nat_res(n: Nat<ColdBig>) -> u64 {
    match n {
        Nat::Small(v) => nat_box(v),
        Nat::Big(_) => big(),
    }
}

/// An `Int` word as the rules take it.
#[inline(always)]
pub fn int_arg(w: u64) -> Int<ColdBig> {
    if w & 1 == 1 {
        Int::Small(int_unbox(w))
    } else {
        Int::Big(cold_big())
    }
}

/// A rule's `Int` result as a word.
#[inline(always)]
pub fn int_res(i: Int<ColdBig>) -> u64 {
    match i {
        Int::Small(v) => int_box(v),
        Int::Big(_) => big(),
    }
}

/// `lean_panic_fn`'s message, the path no benchmark takes.
#[cold]
#[inline(never)]
pub fn lean_panic(msg: &str) {
    eprintln!("{msg}");
}

/// An internal panic, the path no benchmark takes.
#[cold]
#[inline(never)]
pub fn end(p: InternalPanic) -> ! {
    eprintln!("INTERNAL PANIC: {}", p.message());
    std::process::exit(1)
}

/// A new array object of `bytes` bytes, as `lean_alloc_array`/`lean_alloc_sarray` make one: one
/// allocation of that size, its 24-byte header written.
#[inline]
pub fn new_object(bytes: u64) -> Vec<u8> {
    let mut v = Vec::with_capacity(bytes as usize);
    v.extend_from_slice(&[0u8; 24]);
    v
}

/// `ARRAY` Nat words below 2^24 (the LCG's top 24 bits), as `Bench.natOperands`.
pub fn nat_words() -> Vec<u64> {
    let mut x = INPUT_SEED;
    (0..ARRAY)
        .map(|_| {
            x = step(x);
            nat_box(x >> 40)
        })
        .collect()
}

/// `ARRAY` bytes (the LCG's top 8 bits), as `Bench.byteOperands`.
pub fn byte_operands() -> Vec<u8> {
    let mut x = INPUT_SEED;
    (0..ARRAY)
        .map(|_| {
            x = step(x);
            (x >> 56) as u8
        })
        .collect()
}

/// The 64 bytes 0, 1, ..., 63, as `Bench.srcBytes`.
pub fn src_bytes() -> Vec<u8> {
    (0..64).collect()
}

/// 16 characters, escapes among them, as `Bench.charOperands`.
pub fn char_operands() -> Vec<char> {
    vec![
        'a', 'z', '0', ' ', '\n', '\t', '\\', '"', '\'', '\0', '\x1f', '\x7f', '\u{80}', 'é', '€', '😀',
    ]
}

/// 16 strings with escapes, as `Bench.quoteStrings`.
pub fn quote_strings() -> Vec<String> {
    (0..16)
        .map(|k| format!("item {k}: \"q\" \\ tab\there\n{}", "é".repeat(k)))
        .collect()
}

/// The character at index `j` (`Array.get!`: the default 'A' out of range).
#[inline(always)]
pub fn get_char(cs: &[char], j: u64) -> char {
    match cs.get(j as usize) {
        Some(&c) => c,
        None => 'A',
    }
}

/// The string at index `j` (`Array.get!`: the default, "", out of range).
#[inline(always)]
pub fn get_string(ss: &[String], j: u64) -> &str {
    match ss.get(j as usize) {
        Some(s) => s,
        None => "",
    }
}

// ---------------------------------------------------------------- running

/// Runs one benchmark: N from the single argument, the input built before the first clock read,
/// the kernel's result consumed after the second; prints the result and `kernel_ns <ns>`.
pub fn run<I>(build: fn() -> I, kernel: fn(&I, u64) -> u64) {
    let args: Vec<String> = std::env::args().collect();
    let n = match args.as_slice() {
        [_, n] => n.parse::<u64>().ok(),
        _ => None,
    };
    let Some(n) = n else {
        eprintln!("usage: {} N", args[0]);
        std::process::exit(2);
    };
    let input = black_box(build());
    let n = black_box(n);
    let t0 = Instant::now();
    let out = black_box(kernel(&input, n));
    let ns = t0.elapsed().as_nanos();
    println!("{out}");
    println!("kernel_ns {ns}");
}
